258				if err := os.Symlink(missingTarget, linkPath); err != nil {
259					t.Fatal(err)
260				}
261				manifestPath := filepath.Join(root, "in.json")
262				writeFile(t, manifestPath, manifestContent)
263	
264				var stdout bytes.Buffer
265				err := tc.run(linkPath, manifestPath, &stdout)
266				if err == nil {
267					t.Fatal("a dangling registry link must reject the command")
268				}
269				msg := err.Error()
270				if !strings.Contains(msg, linkPath) {
271					t.Errorf("error %q must name the registry path the user passed", msg)
272				}
273				if !strings.Contains(msg, "symbolic link") {
274					t.Errorf("error %q must state the path is an unusable symbolic link", msg)
275				}
276				if stdout.Len() != 0 {
277					t.Errorf("stdout must carry no success result, got %q", stdout.String())
278				}
279				assertStillSymlink(t, linkPath, missingTarget)
280				if _, statErr := os.Stat(missingTarget); !os.IsNotExist(statErr) {
281					t.Errorf("the missing target must not be created, stat err=%v", statErr)
282				}
283				// The manifest is read-only input and must survive untouched.
284				manifest, readErr := os.ReadFile(manifestPath)
285				if readErr != nil {
286					t.Fatal(readErr)
287				}
288				if string(manifest) != manifestContent {
289					t.Errorf("the input manifest changed: %s", manifest)
290				}
291			})
292		}
293	}
